// Extrai da planilha o que sobrou de útil depois da conversão xlsx -> Sheets:
//   B  = nome do anúncio       (texto)
//   K  = nome do arquivo feed  (texto — o hyperlink se perdeu na conversão)
//   L  = nome do arquivo story  (texto)
//   V  = link da PASTA no Drive (link vivo)
// Com pasta + nome dá para achar o fileId depois, sem depender do hyperlink.

const COL = { nome: 1, feed: 10, story: 11, pasta: 21 }; // B, K, L, V (base 0)

const linkDe = (v) =>
  v?.hyperlink ||
  v?.userEnteredFormat?.textFormat?.link?.uri ||
  (v?.textFormatRuns || []).map((r) => r?.format?.link?.uri).find(Boolean) ||
  '';

// aceita link de pasta e também o texto colado como URL
const folderId = (cel) => {
  const bruto = linkDe(cel) || cel?.formattedValue || '';
  return (bruto.match(/\/folders\/([^/?#]+)/) || [])[1] || '';
};

const tipoDe = (nome) =>
  /_vid_/i.test(nome) ? 'video' : (/_car_/i.test(nome) ? 'carrossel' : 'imagem');

const resp = $input.first().json;
const rowData = resp?.sheets?.[0]?.data?.[0]?.rowData || [];
if (rowData.length === 0) {
  throw new Error('A API não devolveu rowData — confira o nome da aba em "ranges" e o escopo da credencial.');
}

const linhas = [];
for (let i = 1; i < rowData.length; i++) { // pula cabeçalho
  const v = rowData[i]?.values || [];
  const nome = (v[COL.nome]?.formattedValue || '').trim();
  if (!/^seal_ad/i.test(nome)) continue;

  const pasta = folderId(v[COL.pasta]);
  const feed = (v[COL.feed]?.formattedValue || '').trim();
  const story = (v[COL.story]?.formattedValue || '').trim();
  if (!pasta || (!feed && !story)) continue; // sem onde ou o que procurar

  linhas.push({
    ad_name: nome,
    tipo: tipoDe(nome),
    drive_folder_id: pasta,
    arquivo_feed: feed || null,
    arquivo_story: story || null,
  });
}

const unicos = [...new Map(linhas.map((l) => [l.ad_name.toLowerCase(), l])).values()];
if (unicos.length === 0) {
  throw new Error('Nenhum criativo com pasta + nome de arquivo — a estrutura da planilha mudou?');
}

return [{ json: { total: unicos.length, rows: unicos } }];

// 1 item por criativo a resolver. Se não há ninguém, encerra sem erro —
// é o estado normal depois que tudo já foi resolvido.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const lista = Array.isArray(j) ? j : (Array.isArray(j.data) ? j.data : [j]);
  for (const r of lista) {
    if (r && r.ad_name && r.drive_folder_id) out.push({ json: r });
  }
}
return out;

// Casa o arquivo do Drive com o criativo. A planilha é inconsistente no nome:
//   - às vezes a coluna K traz o nome completo com extensão ("..._feed.mp4");
//   - às vezes traz um rótulo do carrossel ("02 - PROCURA-SE"), que não existe
//     no Drive — lá os arquivos se chamam pelo NOME DO ANÚNCIO com o número do
//     slide no fim ("seal_ad_0043_vj_car_procura-se.8", ".7", ".6"...).
// Por isso tentamos primeiro pelo nome do arquivo e depois pelo nome do anúncio.
const ctx = $('Normalizar fila').item.json;
const alvo = (ctx.arquivo_feed || ctx.arquivo_story || '').trim();
const arquivos = ($input.item.json.files || []).filter((f) => f && f.id);

const semExt = (s) => String(s).replace(/\.[a-z0-9]{2,4}$/i, '');
const norm = (s) =>
  String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');

const a = norm(alvo);
const aSemExt = norm(semExt(alvo));
const nomeAd = norm(semExt(ctx.ad_name || ''));

// número do slide no fim do nome ("...-procura-se.8" -> 8); sem sufixo vira 0,
// então o arquivo "inteiro" ganha da parte numerada.
const slide = (nome) => {
  const m = String(nome).match(/\.(\d{1,3})$/);
  return m ? Number(m[1]) : 0;
};
const porSlide = (lista) => [...lista].sort((x, y) => slide(x.name) - slide(y.name))[0];

let achado =
  arquivos.find((f) => norm(f.name) === a) ||
  arquivos.find((f) => norm(semExt(f.name)) === aSemExt) ||
  arquivos.find((f) => norm(f.name).startsWith(aSemExt)) ||
  arquivos.find((f) => aSemExt.length > 5 && norm(f.name).includes(aSemExt)) ||
  null;

// Fallback pelo nome do anúncio: pega o slide de menor número (a capa).
if (!achado && nomeAd.length > 5) {
  const doAnuncio = arquivos.filter((f) => norm(semExt(f.name)).startsWith(nomeAd));
  if (doAnuncio.length > 0) achado = porSlide(doAnuncio);
}

// Último recurso para carrossel: a pasta é do próprio criativo, então a
// primeira imagem serve de capa.
if (!achado && arquivos.length > 0 && ctx.tipo === 'carrossel') {
  achado = porSlide(arquivos);
}

if (!achado) {
  const candidatos = arquivos.slice(0, 5).map((f) => f.name).join(' | ') || '(pasta vazia)';
  const msg = 'nao casou "' + alvo + '" em ' + arquivos.length + ' arquivos: ' + candidatos;
  return { json: { ad_name: ctx.ad_name, patch: { erro: msg.slice(0, 300) } } };
}

const usouFeed = Boolean(ctx.arquivo_feed);
return {
  json: {
    ad_name: ctx.ad_name,
    patch: usouFeed
      ? { drive_feed_id: achado.id, erro: null }
      : { drive_story_id: achado.id, erro: null },
  },
};
